/**
 * Главная страница: краткое описание курса, последние материалы
 * и схема того, как ноутбук превращается в страницу сайта.
 */

import { Link } from 'react-router-dom';

import { notebooks, presentations, formatDate } from '../content';
import styles from './Home.module.css';

/** Шаги конвейера публикации материалов. */
const PIPELINE = [
  { icon: 'fa-file-code', title: '.ipynb', text: 'Ноутбук семинара в репозитории' },
  { icon: 'fa-wand-magic-sparkles', title: 'pandoc', text: 'Конвертация в самодостаточный HTML' },
  { icon: 'fa-window-maximize', title: '<iframe srcdoc>', text: 'Встраивание в React-компонент' },
  { icon: 'fa-rocket', title: 'GitHub Pages', text: 'Публикация через npm run deploy' },
];

/** Карточка материала для сетки «последнее». */
function MaterialCard({ item, to, badge }) {
  return (
    <div className="col-12 col-md-6 col-lg-4">
      <Link to={to} className={styles.card}>
        <span className={styles.cardIcon}>
          <i className={`fa-solid ${item.icon}`} aria-hidden="true" />
        </span>

        <span className={styles.cardBadge}>{badge}</span>

        <h3 className={styles.cardTitle}>{item.title}</h3>
        <p className={styles.cardText}>{item.description}</p>

        <span className={styles.cardFooter}>
          <span className="text-body-secondary small">
            <i className="fa-regular fa-calendar me-2" aria-hidden="true" />
            {formatDate(item.date)}
          </span>
          <span className={styles.cardLink}>
            Открыть
            <i className="fa-solid fa-arrow-right ms-2" aria-hidden="true" />
          </span>
        </span>
      </Link>
    </div>
  );
}

export default function Home() {
  const latestNotebooks = notebooks.slice(0, 3);
  const latestPresentations = presentations.slice(0, 3);

  return (
    <div className="container">
      {/* --- Первый экран --- */}
      <section className={styles.hero}>
        <p className={styles.eyebrow}>Курс 4-го года обучения</p>

        <h1 className={styles.heroTitle}>
          Семинары по <span className="ml-gradient-text">машинному обучению</span>
        </h1>

        <p className={styles.heroText}>
          Все материалы курса в одном месте: разобранный код из Jupyter-ноутбуков,
          слайды лекций и задания. Ноутбуки конвертируются в HTML командой{' '}
          <code>pandoc</code> и открываются прямо на странице — ничего скачивать
          и запускать не нужно.
        </p>

        <div className={styles.heroActions}>
          <Link to="/notebooks" className="btn btn-primary btn-lg">
            <i className="fa-solid fa-book me-2" aria-hidden="true" />
            Смотреть ноутбуки
          </Link>
          <Link to="/presentations" className="btn btn-outline-primary btn-lg">
            <i className="fa-solid fa-chalkboard-user me-2" aria-hidden="true" />
            Презентации лекций
          </Link>
        </div>

        <dl className={styles.stats}>
          <div className={styles.stat}>
            <dt>{notebooks.length}</dt>
            <dd>ноутбуков семинаров</dd>
          </div>
          <div className={styles.stat}>
            <dt>{presentations.length}</dt>
            <dd>презентаций лекций</dd>
          </div>
          <div className={styles.stat}>
            <dt>100%</dt>
            <dd>материалов открыты</dd>
          </div>
        </dl>
      </section>

      {/* --- Последние ноутбуки --- */}
      <section className={styles.section}>
        <header className={styles.sectionHeader}>
          <h2 className={styles.sectionTitle}>
            <i className="fa-solid fa-book me-2 text-primary" aria-hidden="true" />
            Свежие ноутбуки
          </h2>
          <Link to="/notebooks" className="btn btn-sm btn-outline-secondary">
            Все ноутбуки
            <i className="fa-solid fa-arrow-right ms-2" aria-hidden="true" />
          </Link>
        </header>

        <div className="row g-3">
          {latestNotebooks.map((item) => (
            <MaterialCard
              key={item.slug}
              item={item}
              to={`/notebooks/${item.slug}`}
              badge="Семинар"
            />
          ))}
        </div>
      </section>

      {/* --- Презентации --- */}
      <section className={styles.section}>
        <header className={styles.sectionHeader}>
          <h2 className={styles.sectionTitle}>
            <i className="fa-solid fa-chalkboard-user me-2 text-primary" aria-hidden="true" />
            Презентации лекций
          </h2>
          <Link to="/presentations" className="btn btn-sm btn-outline-secondary">
            Все презентации
            <i className="fa-solid fa-arrow-right ms-2" aria-hidden="true" />
          </Link>
        </header>

        <div className="row g-3">
          {latestPresentations.map((item) => (
            <MaterialCard
              key={item.slug}
              item={item}
              to={`/presentations/${item.slug}`}
              badge="Лекция"
            />
          ))}
        </div>
      </section>

      {/* --- Как это устроено --- */}
      <section className={styles.section}>
        <h2 className={styles.sectionTitle}>
          <i className="fa-solid fa-gears me-2 text-primary" aria-hidden="true" />
          Как устроен сайт
        </h2>
        <p className="text-body-secondary mb-4">
          Материалы не верстаются руками: страница собирается из исходных .ipynb автоматически.
        </p>

        <ol className={styles.pipeline}>
          {PIPELINE.map((step, index) => (
            <li key={step.title} className={styles.pipelineStep}>
              <span className={styles.pipelineIcon}>
                <i className={`fa-solid ${step.icon}`} aria-hidden="true" />
              </span>
              <span className={styles.pipelineNumber}>Шаг {index + 1}</span>
              <span className={styles.pipelineTitle}>{step.title}</span>
              <span className={styles.pipelineText}>{step.text}</span>
            </li>
          ))}
        </ol>
      </section>
    </div>
  );
}
